INSERT INTO writing_task (task_type, title, description, difficulty) VALUES
('TASK_2', 'Education and technology', 'Some people believe that technology has made education more accessible, while others think it has reduced the quality of learning. Discuss both views and give your own opinion.', 'medium'),
('TASK_2', 'University education', 'Some people think that universities should provide graduates with the knowledge and skills needed in the workplace. Others think that the true function of a university is to give access to knowledge for its own sake. Discuss both views and give your opinion.', 'medium'),
('TASK_2', 'Environmental responsibility', 'Individuals can do nothing to improve the environment; only governments and large companies can make a difference. To what extent do you agree or disagree?', 'medium'),
('TASK_2', 'Remote work', 'More people are working from home than ever before. Do the advantages of this trend outweigh the disadvantages?', 'easy'),
('TASK_2', 'Public transport', 'Governments should spend more money on railways rather than roads. To what extent do you agree or disagree?', 'easy'),
('TASK_2', 'Advertising to children', 'Some people think that advertising aimed at children should be banned. Others believe that it is the responsibility of parents. Discuss both views and give your opinion.', 'medium'),
('TASK_2', 'Health and lifestyle', 'Many people today do not feel healthy despite improvements in medical care. What are the reasons for this and what can be done to solve this problem?', 'medium'),
('TASK_2', 'Cultural heritage', 'Some people believe that governments should protect old buildings, while others think money should be spent on new housing and roads. Discuss both views and give your opinion.', 'hard'),
('TASK_2', 'Gap year', 'In some countries, young people are encouraged to work or travel for a year between finishing high school and starting university. Discuss the advantages and disadvantages.', 'easy'),
('TASK_2', 'Crime and punishment', 'Some people believe that the best way to reduce crime is to give longer prison sentences. Others think there are better ways. Discuss both views and give your opinion.', 'hard'),
('TASK_1', 'City population change', 'The table below shows population figures for three cities in 2000 and 2020, together with projected figures for 2040. Summarise the information by selecting and reporting the main features, and make comparisons where relevant.', 'easy'),
('TASK_1', 'Energy sources', 'The pie charts show the proportion of energy produced from coal, gas, nuclear, and renewable sources in a country in 1990 and 2020. Summarise the information by selecting and reporting the main features.', 'medium'),
('TASK_1', 'Internet users', 'The line graph shows the number of internet users in four countries between 2005 and 2020. Summarise the information by selecting and reporting the main features, and make comparisons where relevant.', 'easy'),
('TASK_1', 'Water consumption', 'The bar chart compares water consumption in agriculture, industry, and households in three regions. Summarise the information by selecting and reporting the main features.', 'medium'),
('TASK_1', 'Process of recycling paper', 'The diagram illustrates the process of recycling paper. Summarise the information by selecting and reporting the main features, and make comparisons where relevant.', 'hard');
